      "den-rozhdeniya": { opening: "В день рождения с утра\nЗакричали все: «Ура!»", closing: "С днём рождения! Потом\nБудет праздник — кувырком!", openingScene: "balloons tied to the bed", closingScene: "a birthday cake with candles and balloons on the bedside table" },
      default: { opening: "Праздник — {ПОВОД} — с утра!\nВсе в ладоши: «Ох! Ура!»", closing: "Праздник — {ПОВОД} — вот:\nПусть идёт наоборот!\nТорт — с утра, а суп — потом.\nВот так праздник — кувырком!" },
